"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[43152],{3331:(e,r,i)=>{i.d(r,{R:()=>a,x:()=>o});var n=i(36672);const t={},s=n.createContext(t);function a(e){const r=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),n.createElement(s.Provider,{value:r},e.children)}},95714:(e,r,i)=>{i.r(r),i.d(r,{assets:()=>l,contentTitle:()=>o,default:()=>m,frontMatter:()=>a,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"2023/04/07","title":"2023-04-07","description":"Hvis vi mister Internet Archive, er vi p\xe5 r\xf8ven","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/07.md","sourceDirName":"2023/04","slug":"/2023/04/07","permalink":"/da/2023/04/07","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/07.md","tags":[],"version":"current","frontMatter":{"localized_date":"7. april 2023","top_news":"Hvis vi mister Internet Archive, er vi p\xe5 r\xf8ven"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-08","permalink":"/da/2023/04/08"},"next":{"title":"2023-04-06","permalink":"/da/2023/04/06"}}');var t=i(23420),s=i(3331);const a={localized_date:"7. april 2023",top_news:"Hvis vi mister Internet Archive, er vi p\xe5 r\xf8ven"},o="2023-04-07",l={},d=[{value:"Hvis vi mister Internet Archive, er vi p\xe5 r\xf8ven",id:"hvis-vi-mister-internet-archive-er-vi-p\xe5-r\xf8ven",level:2},{value:"Chrome sender WebGPU",id:"chrome-sender-webgpu",level:2},{value:"Vis Tabby - en selvhostet GitHub-kopilot",id:"vis-tabby---en-selvhostet-github-kopilot",level:2},{value:"Tesla-medarbejdere delte billeder fra bilkameraer, herunder &quot;scener af intimitet&quot;",id:"tesla-medarbejdere-delte-billeder-fra-bilkameraer-herunder-scener-af-intimitet",level:2},{value:"Simpelthen forklaret: Hvordan virker GPT?",id:"simpelthen-forklaret-hvordan-virker-gpt",level:2},{value:"Systemdesign og omkostningerne ved arkitektonisk kompleksitet (2013)",id:"systemdesign-og-omkostningerne-ved-arkitektonisk-kompleksitet-2013",level:2},{value:"Defamed by ChatGPT",id:"defamed-by-chatgpt",level:2},{value:"Masterplan del 3",id:"masterplan-del-3",level:2},{value:"Tesla-medarbejdere delte f\xf8lsomme billeder optaget af kundebiler",id:"tesla-medarbejdere-delte-f\xf8lsomme-billeder-optaget-af-kundebiler",level:2},{value:"Buck2: Vores open source build-system",id:"buck2-vores-open-source-build-system",level:2},{value:"Mariadb.com er d\xf8d, l\xe6nge leve MariaDB.org",id:"mariadbcom-er-d\xf8d-l\xe6nge-leve-mariadborg",level:2},{value:"Vis ADHD-venlig Pomodoro web-app",id:"vis-adhd-venlig-pomodoro-web-app",level:2},{value:"Meta frigiver nyt AI-baseret v\xe6rkt\xf8j til segmentering af fotos til alle",id:"meta-frigiver-nyt-ai-baseret-v\xe6rkt\xf8j-til-segmentering-af-fotos-til-alle",level:2},{value:"Hvad der sker, n\xe5r du l\xe6kker AWS-oplysninger, og hvordan AWS minimerer skaden",id:"hvad-der-sker-n\xe5r-du-l\xe6kker-aws-oplysninger-og-hvordan-aws-minimerer-skaden",level:2},{value:"Gource - Animer din Git-historik",id:"gource---animer-din-git-historik",level:2},{value:"Vis Generer startup-ideer baseret p\xe5 Discussion Service-kommentarer",id:"vis-generer-startup-ideer-baseret-p\xe5-discussion-service-kommentarer",level:2},{value:"DevOps anvender en kapacitetsmodel, ikke en modenhedsmodel",id:"devops-anvender-en-kapacitetsmodel-ikke-en-modenhedsmodel",level:2},{value:"At tilf\xf8je kapacitet til elnettet er ikke en enkel opgave",id:"at-tilf\xf8je-kapacitet-til-elnettet-er-ikke-en-enkel-opgave",level:2},{value:"Bekendtg\xf8relse af WCGI: WebAssembly og CGI",id:"bekendtg\xf8relse-af-wcgi-webassembly-og-cgi",level:2},{value:"JSON vs. XML",id:"json-vs-xml",level:2},{value:"Webstedet er hostet p\xe5 en 24 \xe5r gammel Linux-server",id:"webstedet-er-hostet-p\xe5-en-24-\xe5r-gammel-linux-server",level:2},{value:"Er det min skyld, hvis du ikke kan h\xe5ndtere sandheden? (2019)",id:"er-det-min-skyld-hvis-du-ikke-kan-h\xe5ndtere-sandheden-2019",level:2},{value:"C Strings og min langsomme nedtur til galskab",id:"c-strings-og-min-langsomme-nedtur-til-galskab",level:2},{value:"MutexProtected: A C++ Pattern for Easier Concurrency",id:"mutexprotected-a-c-pattern-for-easier-concurrency",level:2},{value:"Clarence Thomas og milliard\xe6ren",id:"clarence-thomas-og-milliard\xe6ren",level:2},{value:"Rusts d\xe5rlige sammens\xe6tbarhed",id:"rusts-d\xe5rlige-sammens\xe6tbarhed",level:2},{value:"Spotting and avoiding heap fragmentation in Rust applications",id:"spotting-and-avoiding-heap-fragmentation-in-rust-applications",level:2},{value:"V\xe6r forsigtig med hvad du tester eller implementerer til Vercel",id:"v\xe6r-forsigtig-med-hvad-du-tester-eller-implementerer-til-vercel",level:2},{value:"Linux 6.4 bringer Apple M2 Tilf\xf8jelser til 2022 MacBook og Mac Mini",id:"linux-64-bringer-apple-m2-tilf\xf8jelser-til-2022-macbook-og-mac-mini",level:2},{value:"Illustrationer af &quot;usynlige&quot; japanske vedligeholdelsestog, der kun k\xf8rer om natten",id:"illustrationer-af-usynlige-japanske-vedligeholdelsestog-der-kun-k\xf8rer-om-natten",level:2}];function g(e){const r={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"2023-04-07",children:"2023-04-07"})}),"\n",(0,t.jsx)(r.h2,{id:"hvis-vi-mister-internet-archive-er-vi-p\xe5-r\xf8ven",children:"Hvis vi mister Internet Archive, er vi p\xe5 r\xf8ven"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/",children:"Original"}),'.\nInternet Archive, der beskriver sig selv som "et non-profit bibliotek med millioner af gratis b\xf8ger, film, software, musik, hjemmesider og meget mere", er blevet sags\xf8gt af fire forlag for at have kr\xe6nket ophavsretten, og en f\xf8deral dommer har givet forlagene medhold. Internet Archive appellerer imidlertid afg\xf8relsen, som nogle h\xe6vder, at den grundl\xe6ggende er et angreb p\xe5 skatteyderfinansierede offentlige tjenester fra virksomheder og privatpersoner. Kritikere h\xe6vder, at lukningen af National Emergency Library, som gjorde ophavsretligt beskyttede b\xf8ger gratis tilg\xe6ngelige under COVID-19-pandemien, er langt mere katastrofalt for arbejderklassen, end adgangen til b\xf8ger nogensinde kan v\xe6re. Hvis appellen ikke lykkes, vil menneskene miste mere viden, end Alexandra-biblioteket nogensinde har indeholdt.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468753",children:"Discussion Service"}),".\nDiscussion Service-brugere debatterer ophavsretslove og kulturel bevaring. Juridiske kampe rejser sp\xf8rgsm\xe5l om ophavsrettens legitimitet og statslige monopoler. Nogle opfordrer til bedre forvaltning for at tilskynde til arbejde og kortere ophavsretlige frister. At miste IA kunne omskrive historien og fremh\xe6ve vigtigheden af at bevare viden. Forslag om at starte en ny enhed eller stoppe donationer p\xe5 grund af IA's risikable adf\xe6rd. National Emergency Library ses som uventet og gavnligt, men IA-ledere har et ansvar for at bevare historien."]}),"\n",(0,t.jsx)(r.h2,{id:"chrome-sender-webgpu",children:"Chrome sender WebGPU"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://developer.chrome.com/blog/webgpu-release/",children:"Original"}),'.\nChrome lancerer WebGPU, et nyt webgrafik-API, der tilbyder forbedret 3D-grafik og data-parallel beregning p\xe5 ChromeOS, macOS og Windows, for at give adgang til avancerede GPU-funktioner og effektiv programmering med webplatformen. WebGPU er designet med et idiomatisk JavaScript-API, integration med promises og gode fejlmeddelelser, og det er en byggesten for fremtidige forbedringer, f.eks. adgang til shader-kerner til flere optimeringer af maskinl\xe6ring og st\xf8rre ergonomi i WGSL. WebGPU er resultatet af et seks\xe5rigt samarbejde mellem W3C\'s "GPU for the Web"-f\xe6llesskabsgruppe, herunder bidrag fra Mozilla, Apple, Intel og Microsoft. ChromeOS-, Windows- og macOS-platforme kan underst\xf8tte WebGPU, og Linux, Android og andre platforme vil udvide underst\xf8ttelsen i den n\xe6rmeste fremtid. Popul\xe6re WebGL-biblioteker, som Babylon.js, PlayCanvas og TensorFlow.js, tilbyder allerede en vis WebGPU-underst\xf8ttelse eller arbejder p\xe5 det. Ressourcer til at l\xe6re mere om WebGPU omfatter bl.a. W3C-specifikationer, MDN-dokumentation, eksempler og GPU compute.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35465729",children:"Discussion Service"}),".\nChrome har leveret WebGPU, som lover forbedringer i forhold til WebGL. WebGPU er en game changer med positive bidrag; meningerne varierer om, hvorvidt desktop eller mobile GPU'er b\xf8r prioriteres. Brugere diskuterer m\xe5der at begr\xe6nse informationsl\xe6kre browserfunktioner og forhindre fingerprinting. Der er bekymring over potentiel ondsindet brug til minedrift af kryptovaluta. Web3DSurvey sporer funktioner og begr\xe6nsninger i forbindelse med WebGPU. Der er begejstring over potentialet for, at WebGPU kan blive udbredt, p\xe5 trods af bekymringer om begr\xe6nsninger i forhold til mere effektive grafikteknologier."]}),"\n",(0,t.jsx)(r.h2,{id:"vis-tabby---en-selvhostet-github-kopilot",children:"Vis Tabby - en selvhostet GitHub-kopilot"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://github.com/TabbyML/tabby",children:"Original"}),".\nTabbyML har frigivet Tabby, et selvhostet alternativ til GitHub Copilot, som er open source og on-prem. Den har selvindd\xe6mning uden behov for et DBMS eller en cloud-tjeneste, en web-brugergr\xe6nseflade til visualisering og konfigurationsmodeller og MLOps, en OpenAPI-gr\xe6nseflade og nem integration med eksisterende infrastruktur. Udviklere kan bruge docker-image til nem implementering, og TabbyML underst\xf8tter GPU p\xe5 forbrugerniveau med FP-16 v\xe6gtbelastning og andre optimeringer. Dens FastAPI-server indlejrer en OpenAPI-dokumentation af HTTP API'et."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470915",children:"Discussion Service"}),".\nTabby, et selvhostet GitHub Copilot-alternativ, giver fuld kontrol over data og privatlivets fred, mens modellerne finjusteres. Det sparer tid, men giver anledning til bekymring for privatlivets fred. GitHub-problemer vedr\xf8rende privatlivets fred er overdrevne, og Copilot har begr\xe6nsninger. TabbyML genererer boilerplate-kode og giver anledning til sp\xf8rgsm\xe5l om beskyttelse af kode-IP. Alpha-versionen af Tabby er popul\xe6r p\xe5 trods af mangel p\xe5 professionel vinduesudsmykning og dokumentation. Copilot forudsiger kode n\xf8jagtigt, men har begr\xe6nsninger og kan foresl\xe5 d\xe5rlig kode. Nogle brugere foresl\xe5r en selvhostet version af Copilot og en navne\xe6ndring for at opn\xe5 bedre SEO."]}),"\n",(0,t.jsx)(r.h2,{id:"tesla-medarbejdere-delte-billeder-fra-bilkameraer-herunder-scener-af-intimitet",children:'Tesla-medarbejdere delte billeder fra bilkameraer, herunder "scener af intimitet"'}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://arstechnica.com/tech-policy/2023/04/tesla-workers-shared-images-from-car-cameras-including-scenes-of-intimacy/",children:"Original"}),'.\nTesla-ansatte har angiveligt delt videoer og billeder taget af kameraer fra kundernes biler via et internt meddelelsessystem, som indeholdt "til tider meget invasivt" indhold. P\xe5 trods af at Tesla h\xe6vder, at kameraerne i bilerne er "designet fra bunden til at beskytte privatlivets fred", havde medarbejderne let adgang til kameraernes output og delte indholdet "frit". Intime scener uden n\xf8genhed samt "visse stykker vasket\xf8j og visse seksuelle wellness-artikler" var blandt de elementer, der blev delt. Nogle tidligere medarbejdere h\xe6vdede dog, at der var tale om legitim deling af materiale til arbejdsform\xe5l. Alternativt blev nogle billeder angiveligt delt bredt og bredt set, herunder af ledelsen.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471826",children:"Discussion Service"}),'.\nBrugere diskuterer duplikerede artikler og webstedets retningslinjer for indsendelse af originale kilder. Ingen relevante kommentarer om emnet Tesla, der deler billeder fra bilkameraer, herunder "intimscener".']}),"\n",(0,t.jsx)(r.h2,{id:"simpelthen-forklaret-hvordan-virker-gpt",children:"Simpelthen forklaret: Hvordan virker GPT?"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://confusedbit.dev/posts/how_does_gpt_work/",children:"Original"}),".\nArtiklen diskuterer processen bag GPT-3 og hvordan den bruges til naturlige sproglige samtaler gennem ordindlejring og probabilistiske modeller. Dens styrker omfatter generering af tekst og logisk id\xe9forbindelse, men st\xe5r over for begr\xe6nsninger med falske oplysninger og inputrestriktioner. Der er ligheder og forskelle med den menneskelige hjernes struktur, herunder GPT's begr\xe6nsede sproglige evner og mangel p\xe5 l\xf8bende l\xe6ring. Artiklen rejser ogs\xe5 bevidsthedssp\xf8rgsm\xe5l og bekymringer om tab af arbejdspladser, men bem\xe6rker, at GPT alene ikke kan g\xf8re skade. Forsigtighed er dog n\xf8dvendig i forbindelse med yderligere AI-udvikling, og eksperter forsker i m\xe5der at forhindre negative resultater p\xe5. Tekniske f\xe6rdigheder og iv\xe6rks\xe6tter\xe5nd vil v\xe6re v\xe6rdifulde, da konsekvenserne af GPT stadig er usikre."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466201",children:"Discussion Service"}),".\nHacker News-eksperter debatterer AI-sprogmodellernes muligheder og begr\xe6nsninger, herunder ChatGPT og GPT-4. Nogle er forsigtige med at tilskrive maskiner menneskelignende egenskaber, men ChatGPT udsender pr\xe6cis og kontekstspecifik tekst, hvilket er en del af AGI. Debat om relevansen af Chinese Room-scenariet og om intelligensens og bevidsthedens natur. Opm\xe6rksomheden rettes mod praktiske muligheder og innovation, transformatorers relevans og gr\xe6nserne for tr\xe6ningsdata. Skeptikere bem\xe6rker, at GPT-4 mangler feedbackmekanismer fra biologiske hjerner til trods for, at den genererer menneskelignende tekst."]}),"\n",(0,t.jsx)(r.h2,{id:"systemdesign-og-omkostningerne-ved-arkitektonisk-kompleksitet-2013",children:"Systemdesign og omkostningerne ved arkitektonisk kompleksitet (2013)"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://dspace.mit.edu/handle/1721.1/79551",children:"Original"}),".\nFejlmeddelelsen ",(0,t.jsx)(r.code,{children:"HTTP Status 429 - Too Many Requests"})," angiver, at brugeren har sendt en stor m\xe6ngde foresp\xf8rgsler p\xe5 kort tid."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470905",children:"Discussion Service"}),".\nArtiklen omhandler systemdesign og omkostningerne ved arkitektonisk kompleksitet. Brugerne deler personlige erfaringer med cloud-udbydere og forst\xe5else af komplekse systemer. Kommentarer fremh\xe6ver vigtigheden af enkelhed, god dokumentation og at t\xe6nke fremad. Fordelene og udfordringerne ved softwarearkitektur og balancen mellem enkelhed og kompleksitet debatteres af eksperter. Definitionen af kompleksitet i softwaresystemer diskuteres ogs\xe5."]}),"\n",(0,t.jsx)(r.h2,{id:"defamed-by-chatgpt",children:"Defamed by ChatGPT"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://jonathanturley.org/2023/04/06/defamed-by-chatgpt-my-own-bizarre-experience-with-artificiality-of-artificial-intelligence/",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468540",children:"Discussion Service"}),".\nAI-genereret \xe6rekr\xe6nkelse udg\xf8r en betydelig risiko, og ChatGPT unders\xf8ges med hensyn til dets potentielle ansvar. Brugerne diskuterer ansvaret for dens output og foresl\xe5r, at der opretholdes en standard for forsigtighed. Ansvarssp\xf8rgsm\xe5l i forbindelse med autonome biler diskuteres ogs\xe5, og de juridiske konsekvenser af ChatGPT som et v\xe6rkt\xf8j til at s\xf8ge l\xe6gelig og juridisk r\xe5dgivning. Der er ogs\xe5 blevet rejst bekymringer om sprogmodellernes n\xf8jagtighed og den etiske brug af personlige data. Der er kritik af ChatGPT's p\xe5lidelighed og udbredelse af misinformation, hvilket har f\xf8rt til krav om ansvarsfraskrivelser og bindende serviceaftaler. Krydsfeltet mellem teknologi og samfund er et prim\xe6rt fokus i dette indl\xe6g, med igangv\xe6rende juridiske debatter om ansvarlighed for AI-genererede resultater."]}),"\n",(0,t.jsx)(r.h2,{id:"masterplan-del-3",children:"Masterplan del 3"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.tesla.com/blog/master-plan-part-3",children:"Original"}),".\nTesla offentligg\xf8r Master Plan Part 3, der foresl\xe5r en vej til en b\xe6redygtig global energi\xf8konomi gennem elektrificering og elproduktion og -lagring, med detaljerede antagelser, kilder og beregninger bag forslaget. L\xe6sere er velkomne til at komme med input og deltage i samtalen. Tesla giver ogs\xe5 den amerikanske fuldt elektrificerede eftersp\xf8rgselsprofil, der er anvendt i modelleringen."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35462378",children:"Discussion Service"}),".\nTeslas masterplan del 3 f\xe5r opm\xe6rksomhed p\xe5 Hacker News med diskussioner om fossilfri levevis, gennemf\xf8rligheden af elbiler, investeringer i vedvarende energi og udbredelsen af COVID-19. Brugerne debatterer det praktiske i overgangen til vedvarende energi, den \xf8konomiske byrde af skat for de superrige og v\xe5benisering af venlighed og tolerance i politik. Teslas omd\xf8mme, behandling af medarbejdere og visioner for fremtiden diskuteres ogs\xe5. Redakt\xf8ren skal identificere det prim\xe6re budskab og undg\xe5 politiske eller religi\xf8se fordomme."]}),"\n",(0,t.jsx)(r.h2,{id:"tesla-medarbejdere-delte-f\xf8lsomme-billeder-optaget-af-kundebiler",children:"Tesla-medarbejdere delte f\xf8lsomme billeder optaget af kundebiler"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.reuters.com/technology/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-2023-04-06/",children:"Original"}),'.\nTesla-medarbejdere delte f\xf8lsomme videoer optaget af kameraer i kundebiler mellem 2019 og 2022, if\xf8lge Reuters interviews med ni tidligere Tesla-medarbejdere. Ulykker, trafikale raserier og pinlige situationer var blandt de videoer, der blev delt via Teslas interne meddelelsessystem, nogle offentligt. Virksomhedens meddelelse om kundebeskyttelse fremh\xe6ver anonymitetsgarantien for kameraoptagelser, der ikke er knyttet til kunderne eller deres k\xf8ret\xf8jer, men nogle tidligere medarbejdere kaldte det en "kr\xe6nkelse af privatlivets fred". Tesla reagerede p\xe5 bekymringerne om databeskyttelse ved at foretage \xe6ndringer i Sentry Mode, herunder pulserende forlygter p\xe5 parkerede biler for at advare forbipasserende om, at de kan blive overv\xe5get. Reuters h\xe6vder, at alle citater vil blive forsinket, og det giver links til rettelser og feedback fra sitet.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468855",children:"Discussion Service"}),".\nTesla-medarbejdere delte f\xf8lsomme billeder optaget af kundebiler uden sikkerhedsforanstaltninger for privatlivets fred. Regler om beskyttelse af privatlivets fred med alvorlige konsekvenser b\xf8r h\xe5ndh\xe6ves, og virksomheder skal opbygge privatlivets fred fra bunden. Anekdoter fremh\xe6ver manglen p\xe5 privatlivets fred i forskellige virksomheder og nystartede virksomheder, og Indiens mangel p\xe5 love om digitalt privatliv kritiseres. Datafortrolighed er ikke helt sikkert, og medarbejdere kan se og misbruge private data. De tyske standarder for privatlivets fred er ikke perfekte, men databeskyttelsesmyndighederne vil v\xe6re interesserede i eventuelle databrud hos bilproducenter som f\xf8lge af GDPR-h\xe5ndh\xe6velsen. Der er bekymringer om privatlivets fred i forbindelse med forbundne k\xf8ret\xf8jer, men nogle bem\xe6rker, at der findes lignende sporingsmuligheder i ikke-EV'er. Rapporter tyder p\xe5, at nogle l\xe5ngivere har placeret sporingsenheder p\xe5 biler, selv om det er uklart, om de s\xe6lger dataene."]}),"\n",(0,t.jsx)(r.h2,{id:"buck2-vores-open-source-build-system",children:"Buck2: Vores open source build-system"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://engineering.fb.com/2023/04/06/open-source/buck2-open-source-large-scale-build-system/",children:"Original"}),".\nMeta frigiver Buck2, et open source-byggesystem p\xe5 GitHub, skrevet i Rust. Buck2 adskiller kerne- og sprogspecifikke regler, med interne tests, der indikerer builds 2x hurtigere end Buck1, \xf8get parallelisme og et redesignet konsoloutput. Buck2 kunne v\xe6re egnet til moderat store flersproglige projekter, designet med avancerede funktioner for ydeevne og udtryksfulde, dynamiske afh\xe6ngighedsfunktioner. Meta deler open source tech-projekter, herunder AI, data, udvikling, front-end, sprog, platforme, sikkerhed og VR, uden at der er n\xe6vnt nogen bem\xe6rkelsesv\xe6rdige opdateringer eller udgivelser."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470371",children:"Discussion Service"}),".\nFacebooks open source Buck2 build-system f\xe5r opm\xe6rksomhed for sin inkrementelle beregningsmotor og Windows-underst\xf8ttelse. Discussion Service-brugere diskuterer andre build-v\xe6rkt\xf8jer, herunder Waf, TensorFlow og Py_wheel, og fremh\xe6ver udfordringerne ved h\xe5ndtering af store kodebaser. Buck2 fjerner JVM-afh\xe6ngigheden i Buck1 ved at omskrive den i Rust. Buck2 og Bazel er flersprogede buildsystemer med reproducerbare builds og integrationsmuligheder. Artiklen foresl\xe5r, at man bruger det rigtige v\xe6rkt\xf8j til den rigtige opgave og fokuserer p\xe5 et v\xe6rkt\xf8js st\xe6rke sider. Nogle brugere h\xe6vder, at statisk kompilering \xf8ger kompleksiteten, mens andre advokerer for fordelene ved statisk linkede bin\xe6re filer."]}),"\n",(0,t.jsx)(r.h2,{id:"mariadbcom-er-d\xf8d-l\xe6nge-leve-mariadborg",children:"Mariadb.com er d\xf8d, l\xe6nge leve MariaDB.org"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://medium.com/@imashadowphantom/mariadb-com-is-dead-long-live-mariadb-org-b8a0ca50a637",children:"Original"}),".\nMariaDB.com, den kommercielle enhed, st\xe5r over for fiaskoer p\xe5 grund af d\xe5rlig ledelse, racisme, sexisme og overtr\xe6delser af arbejdsretten. Monty, grundl\xe6ggeren, blev fjernet fra bestyrelsen i juli 2022, og CEO Michael Howards fjendtlige overtagelse f\xf8rte til et fald i aktiernes v\xe6rdi. SEC-indberetninger viser, at MariaDB muligvis er ved at lukke ned, da den st\xe5r over for problemer med at fastholde og rekruttere personale p\xe5 grund af sit omd\xf8mme. Medarbejderne r\xe5des til at planl\xe6gge interviews med andre virksomheder, mens de roser MariaDB.org og open source."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467243",children:"Discussion Service"}),".\nLukning af MariaDB.com f\xf8rer til mistanke om \xf8konomisk ustabilitet. Beskyldninger om partiskhed og uunderbyggede beskyldninger mod MariaDB Corp. m\xf8des med skepsis. Den offentlige mening er delt om MariaDB.org's fremtid. Hacker News tr\xe5d diskuterer p\xe5stande om diskrimination, skifter til sammenligning af MariaDB og Postgres. MariaDB Corporation indgiver konkursbeg\xe6ring, konsekvenserne for udviklingen er usikre. MariaDB PLC's aktier falder med n\xe6sten 70 % siden b\xf8rsintroduktionen, analytikere er bekymrede over uerfaren ledelse og \xe6ndringer i branchen. Tab p\xe5 20 millioner dollars i forbindelse med retssag og SkySQL-fusion bidrager til de finansielle problemer. Fremtidige udviklingsproblemer er ubegrundet p\xe5 grund af virksomhedens sponsorer."]}),"\n",(0,t.jsx)(r.h2,{id:"vis-adhd-venlig-pomodoro-web-app",children:"Vis ADHD-venlig Pomodoro web-app"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://brainpls.work/",children:"Original"}),".\nDa der kun er tale om en kommentar p\xe5 \xe9n linje, er der desv\xe6rre ikke nok oplysninger til at give et kortfattet resum\xe9."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471129",children:"Discussion Service"}),".\n'Brainpls.work' Pomodoro-baseret timer til ADHD-st\xf8tte kritiseres som webbaseret. Forslag fremsat om smartere timer-enhed og forbedringer af browser-appen. Ny opm\xe6rksomhed/flow timer-app frigivet p\xe5 Github, foretr\xe6kkes som native app. Brugere roser personlig flashcard-app til sporing af fremskridt. Feedback omfatter tilf\xf8jelse af h\xf8rbare notifikationer, distraktionsmarkering og visning af lokal tid. App-udvikler kan have ADHD."]}),"\n",(0,t.jsx)(r.h2,{id:"meta-frigiver-nyt-ai-baseret-v\xe6rkt\xf8j-til-segmentering-af-fotos-til-alle",children:"Meta frigiver nyt AI-baseret v\xe6rkt\xf8j til segmentering af fotos til alle"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://arstechnica.com/information-technology/2023/04/meta-introduces-ai-model-that-can-isolate-and-mask-objects-within-images/",children:"Original"}),".\nMeta har udviklet en ny billedsegmenteringsmodel kaldet SAM, der kan isolere ethvert objekt i billeder eller videoer p\xe5 kommando. SAM har til form\xe5l at demokratisere billedsegmenteringsprocessen ved at reducere behovet for specialiseret tr\xe6ning og ekspertise. Teknologien er velegnet til forst\xe5else af websideindhold, billedredigering og augmented reality-applikationer. SAM er bem\xe6rkelsesv\xe6rdig for sin evne til at identificere objekter, der ikke findes i tr\xe6ningsdatas\xe6ttet, og for sin delvist \xe5bne tilgang. Meta har desuden oprettet et datas\xe6t kaldet SA-1B, der omfatter 11 millioner billeder og 1,1 milliarder segmenteringsmasker, som vil blive stillet til r\xe5dighed til forskningsform\xe5l under en Apache 2.0-licens."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468304",children:"Discussion Service"}),".\nMeta frigiver AI-baseret v\xe6rkt\xf8j til segmentering af fotos med \xe5benhed og AI-udvikling rost. Nogle bekymrer sig om platformens levedygtighed. Model tr\xe6net p\xe5 12,6 millioner billeder med \xe5ben kildekode. Brugere kritiserer misvisende artikeltitel og eksisterende segmenteringsv\xe6rkt\xf8jer. Ingen relevans for Chrome-udvidelse eller YC-applikationer."]}),"\n",(0,t.jsx)(r.h2,{id:"hvad-der-sker-n\xe5r-du-l\xe6kker-aws-oplysninger-og-hvordan-aws-minimerer-skaden",children:"Hvad der sker, n\xe5r du l\xe6kker AWS-oplysninger, og hvordan AWS minimerer skaden"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://xebia.com/blog/what-happens-when-you-leak-aws-credentials-and-how-aws-minimizes-the-damage/",children:"Original"}),'.\nEn AWS-bruger l\xe6kkede med vilje sine AWS-oplysninger til et offentligt GitHub-repositorium for at se, hvad der ville ske. Inden for et minut efter l\xe6kningen af legitimationsoplysningerne tilf\xf8jede AWS en "karant\xe6nepolitik" til brugerkontoen og informerede brugeren via e-mail med instruktioner om, hvordan han/hun kunne sikre sin konto. En ondsindet akt\xf8r foretog hurtigt automatiserede API-opkald med de l\xe6kkede legitimationsoplysninger, men det lykkedes ikke p\xe5 grund af begr\xe6nsede tilladelser. AWS bruger en GitHub Secrets Scanning-tjeneste til hurtigt at opdage og reagere p\xe5 l\xe6kkede legitimationsoplysninger. For at forhindre l\xe6kage af legitimationsoplysninger kan brugerne k\xf8re pre-commit-scannere lokalt eller tilf\xf8je en hemmelighedsscanner til deres CI/CD-pipeline.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466675",children:"Discussion Service"}),".\nEn Discussion Service-bruger konfigurerede et projekt til automatisk at l\xe6kke AWS-hemmeligheder og udl\xf8se scanningsprocesser. Det er frustrerende at rotere n\xf8gler med mange p\xe5 en konto. AWS ugyldigg\xf8r tokens i offentlige repositories, men rogues kan have adgang allerede. AWS-brugere r\xe5des til at tale med teamet, f\xf8r de tilbagekalder n\xf8gler i produktionen. AWS-support b\xf8r kontaktes ASAP efter et angreb. Der kan tilf\xf8jes yderligere sikkerhed ved at begr\xe6nse brugen af n\xf8gler til visse IP'er. Et script eller git hook kan forhindre pushing af legitimationsoplysninger. Scannerens programmeringsintention er uklar."]}),"\n",(0,t.jsx)(r.h2,{id:"gource---animer-din-git-historik",children:"Gource - Animer din Git-historik"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://gource.io/",children:"Original"}),".\nGource er en animeret tr\xe6grafikgenerator for softwareprojektmapper, som udviklere kan arbejde p\xe5. V\xe6rkt\xf8jet har indbygget logunderst\xf8ttelse for Git, Mercurial, Bazaar og SVN og kan analysere logs lavet af tredjepartsv\xe6rkt\xf8jer for CVS-repositorier. Gource har omfattende dokumentation, eksempler og kontrolelementer p\xe5 sin wikiside, som omfatter nye funktioner, skrifttyper, filtre og indstillinger som --high-dpi-indstillingen, --file-idle-time-at-end-indstillingen eller --fixed-user-size-indstillingen. Gource 0.54 er den seneste version, som indeholder eksperimentel underst\xf8ttelse af Wayland og fejlrettelser p\xe5 Apple M1. Der findes andre lignende v\xe6rkt\xf8jer som Logstalgia, der ses som et nyttigt v\xe6rkt\xf8j til visualisering af webserver-adgangslogfiler. Hvis du kan lide Gource, kan du vise din p\xe5sk\xf8nnelse og donere til forfatteren for at fremme den fremtidige udvikling af dette og andre open source-projekter."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471420",children:"Discussion Service"}),".\nGource, et v\xe6rkt\xf8j til at animere Git-historikken, er rost til at bestemme projektstruktur, redigeringstendenser & arbejdsm\xf8nstre og bruges ofte til sjov visualisering. Redditors deler at bruge det til at visualisere kommentaraktivitet og kode refaktoriseringer. Nogle virksomheder viser det endda offentligt. Nogle k\xe6mper for at finde praktiske anvendelser, men finder det givende som et refleksionsv\xe6rkt\xf8j. \xc6stetisk tiltalende for mange."]}),"\n",(0,t.jsx)(r.h2,{id:"vis-generer-startup-ideer-baseret-p\xe5-discussion-service-kommentarer",children:"Vis Generer startup-ideer baseret p\xe5 Discussion Service-kommentarer"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://hn-ideas.tjcx.me/",children:"Original"}),".\nIntroduktion af et nyt online-v\xe6rkt\xf8j, der genererer id\xe9er til startup-virksomheder baseret p\xe5 emner fra kommentarer offentliggjort p\xe5 Hacker News. Platformen er udviklet af en person ved navn tjcx og giver brugerne mulighed for at indtaste et emne og modtage en tilf\xe6ldig startup-id\xe9 baseret p\xe5 kommentarer relateret til det p\xe5g\xe6ldende emne. Denne opfindelse kan vise sig at v\xe6re nyttig til at styrke iv\xe6rks\xe6ttere og fremme innovation."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467917",children:"Discussion Service"}),".\nDer er blevet skabt en ny id\xe9generator til startup-ideer ved hj\xe6lp af Discussion Service-kommentarer. Ideerne sp\xe6nder fra seri\xf8se til sarkastiske, herunder en abonnementstjeneste for gedeblod og ans\xe6ttelse af lejemordere. Kommentarerne g\xf8r grin med ideerne, men foresl\xe5r ogs\xe5 platforme for UBI og personlig medicin. Andre forslag omfatter fitness-apps, apparater til temperaturoverv\xe5gning og VR til overv\xe5gning af k\xe6ledyr. Brugerne p\xe5 Discussion Service foresl\xe5r en lang r\xe6kke startup-ideer, herunder kontroversielle ideer som barnelignende sexdukker og laboratorieopdyrket menneskek\xf8d. Blandede resultater rapporteres, idet nogle finder det morsomt og andre ikke s\xe5 nyttigt. N\xf8jagtigheden kritiseres, og politiske eller religi\xf8se kommentarer frar\xe5des."]}),"\n",(0,t.jsx)(r.h2,{id:"devops-anvender-en-kapacitetsmodel-ikke-en-modenhedsmodel",children:"DevOps anvender en kapacitetsmodel, ikke en modenhedsmodel"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://octopus.com/blog/devops-uses-capability-not-maturity",children:"Original"}),".\nDevOps b\xf8r if\xf8lge Steve Fenton bruge en kapacitetsmodel, ikke en modenhedsmodel. I mods\xe6tning til en modenhedsmodel er tilgangen resultatbaseret og tilskynder til at eksperimentere med v\xe6rkt\xf8jer og processer. Den er SEM-baseret, kan tilpasses og er dynamisk; den kan skabe inkrementelle gevinster ved at identificere kapaciteter. Modeller for modenhed kan v\xe6re stive, standardiserede og ikke tage h\xf8jde for unikke forretningsudfordringer. Kapacitetsmodellen forbinder egenskaber med bredere systemresultater. Den strukturelle model er overv\xe6ldende, men b\xf8r bruges til l\xf8bende forbedringer."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466718",children:"Discussion Service"}),'.\nDevOps \xe6ndrede dev-teamets roller og pressede h\xf8jere SysAdmin-f\xe6rdighedsniveauer. Nogle foresl\xe5r alternative udtryk som "platform engineering". Metrikbaseret kapacitetsmodel kritiseret som en salgstale, opfordring til meningsfulde kapaciteter. Dyrk en kultur, hvor man pr\xf8ver nye ting med henblik p\xe5 forretningsudvikling.']}),"\n",(0,t.jsx)(r.h2,{id:"at-tilf\xf8je-kapacitet-til-elnettet-er-ikke-en-enkel-opgave",children:"At tilf\xf8je kapacitet til elnettet er ikke en enkel opgave"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.economist.com/technology-quarterly/2023/04/05/adding-capacity-to-the-electricity-grid-is-not-a-simple-task",children:"Original"}),".\nElnettet st\xe5r over for udfordringer med hensyn til at integrere vedvarende energikilder, og kun f\xe5 udbydere er villige til at udvide transformatorkapaciteten. Konservativ regulering og utilstr\xe6kkelige nettilslutninger begr\xe6nser markedsandelen for vedvarende energikilder, hvilket medf\xf8rer forsinkelser og usikkerhed i forbindelse med nye projekter. Reguleringsmyndighederne anerkender behovet for langsigtede forbindelser med henblik p\xe5 en dekarbonisering af nettet og har indf\xf8rt nye regler til st\xf8tte for projekter for vedvarende energi. Indien planl\xe6gger at tilslutte 500 GW vedvarende kapacitet inden 2030, mens Kina nyder godt af den seneste udvidelse af nettet. Det er dog fortsat afg\xf8rende at optimere k\xf8styring og planl\xe6gningsprocedurer, da opbygningen af netinfrastruktur skal balancere delikate balancer."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35463182",children:"Discussion Service"}),".\nTilf\xf8jelse af kapacitet til elnettet st\xe5r over for udfordringer med hensyn til tilladelser, milj\xf8lovgivning, ejendomsret, ekspropriation og s\xf8gning efter uregistrerede ejere. Landene st\xe5r over for unikke netproblemer, herunder Sydafrikas fors\xf8mte elnet og Nederlandenes netkapacitet, der ikke kan f\xf8lge med investeringerne. Gammel netinfrastruktur genbruges til nye offshore vindm\xf8lleparker i Det Forenede Kongerige, men mange gr\xf8nne projekter har datoer i 2030'erne. Stabilitet i nettet i forhold til fremme af vedvarende energikilder og behovet for brint til energilagring dr\xf8ftes. Udfordringer i forbindelse med vedvarende energikilder omfatter overbygning, lagring og netforbindelse. Sydafrikanerne har f\xe6rre str\xf8mafbrydelser i lande som Tyskland og \xd8strig. Kina er f\xf8rende inden for ultrah\xf8jsp\xe6ndingsligstr\xf8msoverf\xf8rsel. Vedvarende energikilder har aldrig v\xe6ret et problem for nettene, selv om syntetisk inerti og h\xe5ndtering af pludselige forsyningsfald fortsat er en udfordring."]}),"\n",(0,t.jsx)(r.h2,{id:"bekendtg\xf8relse-af-wcgi-webassembly-og-cgi",children:"Bekendtg\xf8relse af WCGI: WebAssembly og CGI"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://wasmer.io/posts/announcing-wcgi",children:"Original"}),".\nWasmer har introduceret WCGI, en teknologi, der kombinerer WebAssembly's kraft med CGI's enkelhed til udvikling p\xe5 serversiden. Den kan genbruge eksisterende CGI-programmer, skabe ultrasm\xe5 pakker med kun forretningslogik og statiske aktiver og k\xf8rer WebAssembly-kode i en sandkasse. Det sikrer st\xf8rre effektivitet, sikkerhed og fleksibilitet i udviklingen p\xe5 serversiden og har potentiale til at omforme landskabet for serverl\xf8se applikationer. Webudviklere kan oprette WCGI-applikationer med Rust og PHP ved at kompilere dem til Wasm, og WCGI-servere kan k\xf8res ved hj\xe6lp af wasmer CLI'en. Wasmer arbejder l\xf8bende p\xe5 at udvide WCGI's muligheder."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35469276",children:"Discussion Service"}),".\nWasmer.io annoncerer WCGI, der giver mulighed for problemfri integration med eksisterende servere; Java Servlets vs. \xe5bne standarder; WebAssembly-l\xf8sninger uden for browseren. Java-applets, GWT og JVM diskuteres. WCGI har hukommelsesisolering, CGI-udgangsmuligheder og eliminerer behovet for milj\xf8variabler. Test af Wordpress's ydeevne med WCGI. Udviklere bruger WASM og Wasmer til at inkludere native kode, reducere forsinkelser og forbedre portabiliteten. H\xf8jsikker app-ressourceallokering og modulstyring. K\xf8retidshastighed langsommere p\xe5 WebAssembly sammenlignet med native."]}),"\n",(0,t.jsx)(r.h2,{id:"json-vs-xml",children:"JSON vs. XML"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://corecursive.com/json-vs-xml-douglas-crockford/#",children:"Original"}),".\nDoug Crockford, skaberen af JSON, deler sin historie i CoRecursive-podcasten og diskuterer sine kampe mod XML, JavaScript's historie og sin rolle i forbindelse med at g\xf8re JSON til en standard. Han reflekterer ogs\xe5 over sin karriere og opfordrer udviklere til at tage nye paradigmer til sig. Discussion Service-brugere deler deres erfaringer og tanker om forskellige teknologirelaterede emner. Generelt set giver disse indl\xe6g v\xe6rdifuld indsigt for fagfolk, der \xf8nsker at udvide deres viden."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467711",children:"Discussion Service"}),".\nEksperter diskuterer fordele og ulemper ved XML og JSON, hvor nogle foretr\xe6kker XML til komplekse data, mens andre foresl\xe5r JSON p\xe5 grund af dets enkelhed og udbredte anvendelse. Douglas Crockford er \xe6ret blandt programm\xf8rer og har en s\xe6rlig plads i JS-entusiasternes hjerter. Brugerne diskuterer fordele og ulemper ved forskellige dataformater og programmeringssprog, uden at der findes nogen klar l\xf8sning p\xe5 de iboende kompromiser. P\xe5 trods af debatten findes der en grund til, at der findes forskellige formater, og de b\xf8r v\xe6lges i overensstemmelse med situationelle behov. Adam Bosworth h\xe6vder, at HTML's eksplosive udbredelse skyldtes dets begr\xe6nsninger, ikke p\xe5 trods af dem, og at XML var for komplekst for almindelige brugere."]}),"\n",(0,t.jsx)(r.h2,{id:"webstedet-er-hostet-p\xe5-en-24-\xe5r-gammel-linux-server",children:"Webstedet er hostet p\xe5 en 24 \xe5r gammel Linux-server"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://raq.serialport.org/",children:"Original"}),".\nDa der ikke er angivet noget r\xe5tekstindhold, er jeg ikke i stand til at give et resum\xe9 til denne opgave."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468637",children:"Discussion Service"}),".\nEn 24 \xe5r gammel Linux-server k\xf8rer stadig med NetBSD og Apache og hoster et websted. Brugerne mindes for\xe6ldet webteknologi, og nogle foresl\xe5r nye m\xe5der at implementere g\xe6steb\xf8ger eller visningst\xe6llere p\xe5. Der er ogs\xe5 en diskussion om samtidig filadgang og samfundets holdninger til programmering. Det er ikke praktisk muligt at hoste et websted p\xe5 for\xe6ldet hardware til servering af sider i dag. Nogle finder det vanskeligt at f\xe5 adgang til serveren p\xe5 grund af cloudflare."]}),"\n",(0,t.jsx)(r.h2,{id:"er-det-min-skyld-hvis-du-ikke-kan-h\xe5ndtere-sandheden-2019",children:"Er det min skyld, hvis du ikke kan h\xe5ndtere sandheden? (2019)"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://agileotter.blogspot.com/2019/09/is-it-my-fault-you-cant-handle-truth.html",children:"Original"}),".\nArtiklen advarer mod farerne ved overdreven rationalitet og fremh\xe6ver, at det nogle gange er vigtigere at v\xe6re hj\xe6lpsom end at have ret. Den forklarer, hvordan overdrevent rationelle personer kan mangle empati og skabe magtspil. Artiklen n\xe6vner et eksempel p\xe5 en positiv probleml\xf8sningstilgang og stiller sp\xf8rgsm\xe5l til l\xe6serne om at gemme sig bag rationalitet for at undg\xe5 ansvar. Kommentarerne i Hacker News-diskussionen omfatter emner som produktivitet og agil metodologi, hvor brugerne ber\xf8rer rationalitet og dysfunktion i virksomheder. En bruger foresl\xe5r en bog om agilitet som reference. Der blev ikke n\xe6vnt nye teknologier eller udgivelser."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35475482",children:"Discussion Service"}),".\nEn artikel l\xe6gger v\xe6gt p\xe5 at vejlede snarere end at fort\xe6lle folk sandheden, da fakta ofte er ineffektive. Discussion Service-brugere diskuterer vigtigheden af empati og kontekst og rejser sp\xf8rgsm\xe5l om at f\xe5 gl\xe6de af vrede. Eksperter diskuterer balancen mellem \xe6rlighed og venlighed og behovet for empati, respekt og videnskabelig stringens. Debatten drejer sig om videnskabens form\xe5l, om at finde sandheden og om spilteori. Effektiv formidling af sandheden kr\xe6ver takt, timing og relationsopbygning, da fors\xf8mmelse f\xf8rer til grusomhed og magtkampe. Nogle h\xe6vder, at objektiv sandhed i visse sammenh\xe6nge kan v\xe6re respektl\xf8s, og at det er forkert at antage en sandhed."]}),"\n",(0,t.jsx)(r.h2,{id:"c-strings-og-min-langsomme-nedtur-til-galskab",children:"C Strings og min langsomme nedtur til galskab"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.deusinmachina.net/p/c-strings-and-my-slow-descent-to",children:"Original"}),".\nDiego Crespo diskuterer C String-manipulation og almindelige funktioner som strcpy og strlen samt de potentielle problemer, der opst\xe5r ved at arbejde med disse funktioner. Udfordringerne ved at arbejde med ikke-latinske sprog, specielt Unicode- og UTF-8-kodning, beskrives detaljeret med mulige l\xf8sninger. Vigtigheden af forsigtighed under arbejdet med C Strings for at undg\xe5 udefineret adf\xe6rd og potentielle angreb understreges. Crespo bem\xe6rker ogs\xe5, at C++ undg\xe5r nogle af disse problemer ved at behandle strings som objekter. L\xe6serne opfordres til at tjekke forfatterens konti p\xe5 sociale medier og artikler om programmeringssprog og kodning p\xe5 lavt niveau."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467367",children:"Discussion Service"}),".\nDiscussion Service-brugere diskuterer iboende sikkerhedsproblemer i C's h\xe5ndtering af strenge, foresl\xe5r brug af alternative biblioteker og fremh\xe6ver behovet for bedre hukommelsesstyring. Det diskuteres, om C er praktisk anvendeligt til behandling af strenge, og nogle anbefaler allokatorer eller containere. Standard C-biblioteker kritiseres for ineffektivitet, og brugerne foresl\xe5r at omd\xf8be strlen-funktionen for at g\xf8re den mere l\xe6sbar. Kommentarerne omhandler ogs\xe5 fejl for\xe5rsaget af strncpy() og nuancer af Unicode. C entusiaster forsvarer sprogets adgang og kontrol, mens andre finder det for komplekst, og diskuterer forskellige metoder til h\xe5ndtering af strenge i C. Der gives r\xe5d til at undg\xe5 almindelige faldgruber ved h\xe5ndtering af strenge i C. Der udtrykkes frustration, og der foresl\xe5s alternative strengbiblioteker frem for almindelige arrays. P\xe5 trods af C's popularitet mangler der en effektiv l\xf8sning til h\xe5ndtering af strenge."]}),"\n",(0,t.jsx)(r.h2,{id:"mutexprotected-a-c-pattern-for-easier-concurrency",children:"MutexProtected: A C++ Pattern for Easier Concurrency"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://awesomekling.github.io/MutexProtected-A-C++-Pattern-for-Easier-Concurrency/",children:"Original"}),".\nArtiklen forklarer udfordringerne ved at programmere samtidige applikationer ved hj\xe6lp af l\xe5se og pr\xe6senterer et C++-m\xf8nster kaldet MutexProtected, som forenkler processen. Forfatteren bruger et eksempel i C til at demonstrere behovet for MutexProtected og udarbejder et barebones-eksempel. Artiklen introducerer derefter en C++ RAII-klasse til at l\xf8se problemet med glemt opl\xe5sning af mutex, men viser dens mangler. Derefter pr\xe6senterer forfatteren MutexProtected som en kraftfuld konstruktion, der kombinerer en mutex og en datatype for at sikre korrekt samtidig adgang til data. Artiklen afsluttes med introduktionen af MemoizedTreeMap, en implementering af et tr\xe6baseret kort, der anvender MutexProtected til at sikre tr\xe5dsikkerhed."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35464152",children:"Discussion Service"}),".\nMutexProtected er et C++-m\xf8nster til nem samtidighed ligesom Rusts mutexes. Boost.synchronized er komplekst, men kan bruges kun i overskrifter. Kommentarer foresl\xe5r lambda og RAII-style eller eksplicit lock and unlock, og scoped_lock for multiple locks. Eksperter diskuterer mutexes versus channels for samtidighed."]}),"\n",(0,t.jsx)(r.h2,{id:"clarence-thomas-og-milliard\xe6ren",children:"Clarence Thomas og milliard\xe6ren"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.propublica.org/article/clarence-thomas-scotus-undisclosed-luxury-travel-gifts-crow",children:"Original"}),".\nProPublica rapporterer, at dommer Clarence Thomas angiveligt har accepteret luksusrejser fra den republikanske donor Harlan Crow i over to \xe5rtier uden at oplyse dem p\xe5 de \xe5rlige finansielle oplysninger, hvilket giver anledning til etiske bet\xe6nkeligheder. Crow, der har brugt millioner p\xe5 konservativ politik, ejer en yacht og et privatfly, som Thomas har rejst med, og han har v\xe6ret v\xe6rt for ham p\xe5 sin ranch i Texas og p\xe5 sit private feriested. Crow's adgang til retf\xe6rdigheden omfatter alle, som forretningsmanden v\xe6lger at invitere med, hvilket potentielt er i strid med lovene om offentligg\xf8relse af oplysninger. Den opdaterede etiske vejledning for dommere pr\xe6ciserer, at der kr\xe6ves oplysning om s\xe5danne ophold, herunder en tur i 2021 til en katolsk kirkeg\xe5rd n\xe6r New York City, hvor en bronzestatue af Thomas' l\xe6rer fra ottende klasse blev afsl\xf8ret med finansiering fra Crow."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467948",children:"Discussion Service"}),".\nEn vigtig dommer ved USA's h\xf8jesteret kunne v\xe6re indblandet i betydelig korruption, da han kan have modtaget ulovlige tjenester fra en milliard\xe6r; det er dog usandsynligt, at disse handlinger ville f\xf8re til en rigsretssag i dagens ultrapolitiske klima. Selv om dommer Thomas m\xe5ske ikke er bundet af de lavere domstoles etiske regler, kan der stadig tr\xe6ffes retlige foranstaltninger, herunder en unders\xf8gelse fra justitsministeriet eller IRS. Den tilsyneladende korruption fra dommerstandens niveau understreger de superriges korrumperende indflydelse p\xe5 de statslige institutioner, med forudsigelig succes indtil videre. P\xe5 trods af at det er en \xe5benlys overtr\xe6delse af loven, kan dommer Thomas' handlinger g\xe5 ustraffet hen, delvis p\xe5 grund af en afvisning af at stille magthaverne til ansvar."]}),"\n",(0,t.jsx)(r.h2,{id:"rusts-d\xe5rlige-sammens\xe6tbarhed",children:"Rusts d\xe5rlige sammens\xe6tbarhed"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://thedav.is/post/rusts-poor-composability/",children:"Original"}),".\nForfatteren diskuterer Rusts d\xe5rlige sammens\xe6tbarhed og fremh\xe6ver syntaks-problemer med for-loops og iteratorer, og hvordan det p\xe5virker virkelige brugssituationer; forfatteren kritiserer Rusts manglende fleksibilitet og sammens\xe6tbarhed og argumenterer for en opbremsning i sprogudviklingen for at fokusere p\xe5 ergonomi; forfatteren n\xe6vner det igangv\xe6rende arbejde med n\xf8gleord generics og referencer for at forbedre sammens\xe6tbarheden."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468168",children:"Discussion Service"}),".\nBrugere diskuterer Rusts sammens\xe6tbarhed: nogle roser dets alsidighed, andre kritiserer dets ufleksibilitet med iteratorer. Rusts kraft og typesystem beundres, men nogle finder dens syntaks besv\xe6rlig. Holdene b\xf8r fokusere p\xe5 ergonomi, selv om nogle foresl\xe5r at bruge andre sprog, hvis Rust ikke kan lide det. Discussion Service-tr\xe5den diskuterer Rusts programmeringsf\xe6lder, closures og iterativ model. Rusts syntaks, effektsystem og begr\xe6nsninger med closures bliver kritiseret. Der opst\xe5r kompositabilitetsproblemer med Rusts async closures og underst\xf8ttelse af levetid. Rust eksperimenterer med generisk kode over sync+async, mens Goroutines og Zig har denne funktion."]}),"\n",(0,t.jsx)(r.h2,{id:"spotting-and-avoiding-heap-fragmentation-in-rust-applications",children:"Spotting and avoiding heap fragmentation in Rust applications"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.svix.com/blog/heap-fragmentation-in-rust-applications/",children:"Original"}),".\nEt Rust-projekt stod over for ubegr\xe6nset hukommelsesv\xe6kst, sandsynligvis for\xe5rsaget af heap-fragmentering, som blev l\xf8st ved at udskifte allokatoren med jemalloc for at opn\xe5 en bedre hukommelsesprofil. En benchmark.yml i projektets repo tester forskellige inputs. Svix s\xf8ger Rust-eksperter til en skalerbar tjeneste for deres f\xe6llesskab."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35469632",children:"Discussion Service"}),".\nEn artikel diskuterer at undg\xe5 heap-fragmentering i Rust-applikationer, og foresl\xe5r jemalloc kan hj\xe6lpe. Kommentarer foresl\xe5r komprimering af heap, handles, tcmalloc. Valg af de rigtige heap-muligheder og kompromiser diskuteres. Open source-projekternes markedsf\xf8ring og lokalisering af heap-fragmentering n\xe6vnes. jemalloc anbefales til en HTTP-server med h\xf8jt hukommelsesforbrug p\xe5 grund af Rusts blokallokering. Rusts typesystemets effektivitet v\xe6rds\xe6ttes, 99,999 % SLA opn\xe5et gennem test og redundans."]}),"\n",(0,t.jsx)(r.h2,{id:"v\xe6r-forsigtig-med-hvad-du-tester-eller-implementerer-til-vercel",children:"V\xe6r forsigtig med hvad du tester eller implementerer til Vercel"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://twitter.com/shoeboxdnb/status/1643639119824801793",children:"Original"}),".\nArtiklen advarer om, at man skal v\xe6re forsigtig, n\xe5r man tester eller implementerer til Vercel, da det kan resultere i en sortlistet IP-adresse. Brugere fort\xe6ller om personlige erfaringer med Vercels IP-forbud og n\xe6vner problemer med deres teams produktivitet og kommunikation. Nogle antyder, at forbuddet kan v\xe6re forbundet med Vercels misforst\xe5ede fors\xf8g p\xe5 at forhindre misbrug. L\xf8sningerne omfatter kontakt til kundeservice eller skift til en anden tjeneste. En Discussion Service-kommentar fremh\xe6ver vigtigheden af cloud-infrastruktursikkerhed og korrekt testning."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35474837",children:"Discussion Service"}),".\nVercel l\xf8ser faktureringsproblemer og unders\xf8ger forbrugsgr\xe6nser. Nogle kritiserer tilbagebetalingsprocessen. Optimering af cloud-omkostninger er vigtig. Vercel sammenlignet med AWS App Runner og andre billigere alternativer. Serverless kan f\xf8re til uventet fakturering."]}),"\n",(0,t.jsx)(r.h2,{id:"linux-64-bringer-apple-m2-tilf\xf8jelser-til-2022-macbook-og-mac-mini",children:"Linux 6.4 bringer Apple M2 Tilf\xf8jelser til 2022 MacBook og Mac Mini"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.phoronix.com/news/Apple-M2-Device-Tree-Linux-6.4",children:"Original"}),".\nTilf\xf8jelser til Device Tree (DT) for Apples M2-enheder, herunder MacBook Air, MacBook Pro og Mac Mini, vil blive tilf\xf8jet til Linux 6.4. Hector Martin, Asahi Linux' ledende udvikler, indsendte Apple SoC DT-opdateringerne til at blive sat i k\xf8 i SoC-tr\xe6et forud for \xe5bningen af sammenl\xe6gningsvinduet i slutningen af m\xe5neden. Tilf\xf8jelsen af Apple M2 Device Tree-serien og underst\xf8ttelse af den v\xe6sentlige hardware i maskinerne p\xe5 DT vil give meget tiltr\xe6ngt opstr\xf8ms kerneunderst\xf8ttelse for Apple M2. Enheden er dog stadig ikke anvendelig for slutbrugere endnu, og personer, der \xf8nsker den bedste Apple M1/M2 Linux-oplevelse, skal bruge en downstream-distribution som Asahi Linux."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470392",children:"Discussion Service"}),".\nLinux 6.4 tilf\xf8jer Apple M2-underst\xf8ttelse for 2022 MacBook/Mac Mini. Discussion Service-brugere sammenligner Linux/MacOS str\xf8mstyring. Asahi Linux endnu ikke en perfekt l\xf8sning. En vis begejstring, men frustration over kvaliteten af kommentarerne. Brugere beklager sig over misinformation/svindel. Kvaliteten af diskussionen er blevet forringet p\xe5 et bestemt omr\xe5de. En bruger foresl\xe5r at blokere det. Resten af tr\xe5den synes ikke at v\xe6re ber\xf8rt."]}),"\n",(0,t.jsx)(r.h2,{id:"illustrationer-af-usynlige-japanske-vedligeholdelsestog-der-kun-k\xf8rer-om-natten",children:'Illustrationer af "usynlige" japanske vedligeholdelsestog, der kun k\xf8rer om natten'}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.spoon-tamago.com/toei-project-unseen-maintenance-trains/",children:"Original"}),'.\nKunstneren Masami Onishi har illustreret Japans sj\xe6ldent sete arbejdsstyrke af nattog, der udf\xf8rer vedligeholdelsesarbejde p\xe5 spor og elektriske ledninger i de tidlige morgentimer, hvilket sikrer en gnidningsl\xf8s og uafbrudt drift hele dagen. De detaljerede illustrationer af disse tog er en del af Tokyo Metropolitan Bureau of Transportation\'s Project Toei. De omfatter "skinneslibningsvognen", der udglatter slid p\xe5 skinnerne, og "elinspektionsvognen", der vurderer h\xf8jden, sp\xe6ndingen og forholdene p\xe5 de elektriske luftledninger. Japans jernbaner har en bem\xe6rkelsesv\xe6rdigt lav andel af afsporinger, idet der kun er registreret to s\xe5danne h\xe6ndelser i hele landet i 2018.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35474895",children:"Discussion Service"}),'.\nIllustrationer af "usynlige" japanske vedligeholdelsestog, der kun arbejder om natten, fremh\xe6vet gennem projekt Toei. Lokale i NYC kommenterer den utilstr\xe6kkelige vedligeholdelse af metroen d\xf8gnet rundt og giver nogle af dem skylden for for\xe6ldede erhverv som f.eks. d\xf8roperat\xf8rer. Afbilder kontrasten mellem rene metrovogne i Tokyo og d\xe5rlig vedligeholdelse i New York, hvilket f\xf8rer til en diskussion om d\xe5rlig infrastruktur i andre amerikanske byer. Japanske jernbaner nyder godt af private investorer og statslige midler, hvilket st\xe5r i kontrast til tabet af offentlig transport i USA, der betragtes som et offentligt gode. Tokyos hovedstadsregering ejer mange tog, der vedligeholdes af sofistikerede AI-systemer med planer om at v\xe6re fuldt autonome i 2032. Tokyo myldretid er mindre ubehageligt end London eller New York, med reserverede siddepladser.']})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);